'use strict';
// The second campaign has its own fresh save; keep the completed valley as a backup.
function isDesertCampaign(){return state.campaign?.stage==='desert'}
function startDesertCampaign(){
 if(pendingCampaignSave!==null||isDesertCampaign()||!state.victory?.won)return false;
 if(!save())return false;
 const next={appearance:JSON.parse(JSON.stringify(state.appearance||{})),starterPacks:{...(state.starterPacks||{})},gems:state.gems||0,gemRewards:{...(state.gemRewards||{})},campaign:{stage:'desert',valleyWon:true},p:{x:120*T,y:120*T},wood:100,stone:50,food:65,gold:0,cut:[],buildings:[{x:118,y:120,type:'start'}],seen:[],settled:null,chopped:0,time:0,open:true,clock:{paused:false,speed:1},life:{weatherVisible:false},victory:{won:false,dismissed:false}};
 try{const valley=localStorage.getItem(KEY);localStorage.setItem(KEY+'-valley-victory',valley);localStorage.setItem(KEY,JSON.stringify(next))}catch{say('Brak miejsca na nowy etap. Dolina pozostaje bez zmian.');return false}
 // Reload resets every pathfinding queue, actor and cache rather than carrying them across worlds.
 pendingCampaignSave=JSON.stringify(next);state.clock.paused=true;keys={};target=null;location.reload();return true;
}
function initDesertCampaign(){if(!isDesertCampaign())return;for(let i=0;i<state.towns.length;i++){const t=state.towns[i];t.name=['Obóz Krwawego Kła','Obóz Czarnego Topora','Obóz Pustynnej Hordy','Obóz Spalonej Skały'][i%4]+' '+(i+1);t.color='#91a35b';t.faction='orc';if(t.relation!=='conquered'){t.relation=t.scoutFound?'war':'scouting';t.raidTimer=t.scoutFound?(t.raidTimer||45):45;t.truce=0}}if(!state.campaign.orcScouting){state.war.raids=state.war.raids.filter(r=>!state.towns.some(t=>t.id===r.townId&&t.relation==='scouting'));state.campaign.orcScouting=1;state.campaign.scoutClock=10}state.war.support=[];state.life.weatherVisible=false;rebuildForeignIndex();warPanelSignature='';document.body.classList.add('desert-campaign');$('campaignChapter').textContent='ETAP II · PUSTYNIA ORKÓW';$('campaignHeading').textContent='Ostatnia wyprawa.';save()}
const desertTree=tree;tree=function(x,y,h){if(!isDesertCampaign())return desertTree(x,y,h);artLine([[x,y+15],[x+3,y-11],[x-1,y-36]],'#8f633b',6);for(let i=0;i<5;i++){const a=-Math.PI+i*Math.PI/4,dx=Math.cos(a)*24;polygon([[x-1,y-36],[x+dx,y-36+Math.sin(a)*19],[x+dx*.7,y-28+Math.sin(a)*8]],i%2?'#667d42':'#4f713c')}artRect(x-5,y-33,7,5,'#b1874a')};
const desertStructure=structure;structure=function(b,x,y){if(!isDesertCampaign()||!b.type.startsWith('foreign_'))return desertStructure(b,x,y);const t=state.towns.find(t=>t.id===b.townId),owned=t?.relation==='conquered';if(t?.fortBroken&&['foreign_keep','foreign_tower'].includes(b.type))return drawStrategyStructure({type:'ruiny'},x,y);ctx.fillStyle='#59482d44';ctx.beginPath();ctx.ellipse(x+3,y+13,27,9,0,0,7);ctx.fill();if(b.type==='foreign_tower'){artRect(x-15,y-39,5,54,'#5a4430');artRect(x+10,y-39,5,54,'#5a4430');artLine([[x-12,y+12],[x+12,y-26],[x-12,y-26],[x+12,y+12]],'#856139',4);artRect(x-21,y-42,42,13,'#855738');for(let i=-21;i<22;i+=8)polygon([[x+i,y-38],[x+i+4,y-53],[x+i+7,y-38]],'#e3d2a5')}else{const big=b.type==='foreign_keep',w=big?29:24;polygon([[x-w,y+10],[x,y-(big?48:35)],[x+w,y+10]],owned?'#9b9555':'#9a5e3e');polygon([[x,y-(big?48:35)],[x+w,y+10],[x+6,y+10]],'#653f2e');polygon([[x-8,y+10],[x,y-10],[x+9,y+10]],'#302d23');artLine([[x-w,y+10],[x,y-(big?48:35)],[x+w,y+10]],'#d7bd80',2);if(big){artRect(x-1,y-73,3,31,'#5c4530');polygon([[x+2,y-73],[x+26,y-66],[x+2,y-55]],owned?'#dfc46d':'#763f30');ctx.fillStyle='#e4d6af';ctx.font='18px serif';ctx.fillText(owned?'⚑':'☠',x+4,y-57)}}};
const desertTrooper=drawTrooper;drawTrooper=function(x,y,color,actor){desertTrooper(x,y,color,actor);if(!isDesertCampaign()||!['#b65e4c','#b87661','#ad8866'].includes(color))return;drawOrcFace(x,y)};
function drawOrcFace(x,y){ctx.fillStyle='#829a4f';ctx.beginPath();ctx.arc(x,y-23,7,0,7);ctx.fill();polygon([[x-5,y-24],[x-13,y-28],[x-7,y-19]],'#829a4f');polygon([[x+5,y-24],[x+13,y-28],[x+7,y-19]],'#829a4f');artRect(x-4,y-25,2,2,'#e8c85c');artRect(x+2,y-25,2,2,'#e8c85c');polygon([[x-4,y-18],[x-3,y-23],[x-1,y-18]],'#eee0b7');polygon([[x+1,y-18],[x+3,y-23],[x+4,y-18]],'#eee0b7')};
const desertBanditArcher=drawBanditArcher;drawBanditArcher=function(u){desertBanditArcher(u);if(isDesertCampaign())drawOrcFace(u.x,u.y)};
const desertUI=ui;ui=function(){desertUI();if(!isDesertCampaign())return;$('objective').textContent='Etap II — Pustynia orków. Zbuduj nową bazę, wyszkol wojsko i przejmij wszystkie 100 obozów. To ostatni etap gry.';$('warOpen').textContent='⚔ Obozy orków i wojsko'};
initDesertCampaign();if(isDesertCampaign()){ui();say("Dotarłeś na pustynię. Zbuduj bazę i pokonaj 100 obozów orków.")}
